const {test}=require('node:test'),assert=require('node:assert/strict');
test('one metre space survives rotation and translation without rescaling',async()=>{const {toWorld,toLocal}=await import('../scale-study/space.mjs');for(const angle of [0,60,120,180,240,300])for(const offset of [-1,-.25,0,.75,1]){const a=toWorld([0,0],angle,offset),b=toWorld([1,0],angle,offset);assert(Math.abs(Math.hypot(b[0]-a[0],b[1]-a[1])-1)<1e-9);const p=toLocal(toWorld([2.75,-.75],angle,offset),angle,offset);assert(Math.abs(p[0]-2.75)<1e-9&&Math.abs(p[1]+.75)<1e-9);}});
test('every shop transform has a continuous clearance-safe path through the actual door',async()=>{const {DOOR_Z,RECEIVING,findRoute,blocked,toLocal,onRoute,routeLength}=await import('../scale-study/space.mjs');for(const angle of [0,60,120,180,240,300])for(const offset of [-1,-.75,-.5,-.25,0,.25,.5,.75,1]){const p=findRoute(angle,offset);assert.deepEqual(p[0],[-7.5,8.5]);let doorway=false;for(let d=0;d<routeLength(p);d+=.025){const q=toLocal(onRoute(p,d).position,angle,offset);if(Math.abs(q[0])<.25&&Math.abs(q[1]-DOOR_Z)<.1)doorway=true;}assert(doorway);for(let d=0;d<routeLength(p);d+=.05)assert(!blocked(onRoute(p,d).position,angle,offset));const end=toLocal(p.at(-1),angle,offset);assert(Math.abs(end[0]-RECEIVING[0])<1e-9&&Math.abs(end[1]-RECEIVING[1])<1e-9);}});

test('hex neighbors are equidistant and fine-grid centers align under each allowed transform',async()=>{const {HEX_NEIGHBORS,hexCenter,nearestHex,toWorld}=await import('../scale-study/space.mjs');assert.equal(HEX_NEIGHBORS.length,6);for(const d of HEX_NEIGHBORS)assert(Math.abs(Math.hypot(...hexCenter(d))-.25)<1e-9);for(const angle of [0,60,120,180,240,300])for(const offset of [-1,-.25,0,.75,1])for(const axial of [[1,2],[-2,3],[0,0]]){const p=toWorld(hexCenter(axial),angle,offset),snapped=hexCenter(nearestHex(p));assert(Math.hypot(p[0]-snapped[0],p[1]-snapped[1])<1e-9);}for(const a of [[1,1],[-3,2]])assert.deepEqual(hexCenter(a,1),hexCenter(a.map(v=>v*4),.25));});

test('hex shell has six equal sides with solid walls except its real doorway',async()=>{const {FOOTPRINT,WALLS,DOOR_Z,blocked,insideBuilding}=await import('../scale-study/space.mjs');assert.equal(FOOTPRINT.length,6);assert.equal(WALLS.length,7);for(let i=0;i<6;i++){const a=FOOTPRINT[i],b=FOOTPRINT[(i+1)%6];assert(Math.abs(Math.hypot(b[0]-a[0],b[1]-a[1])-4.5)<1e-9);if(i!==1)assert(blocked([(a[0]+b[0])/2,(a[1]+b[1])/2]));}assert(!blocked([0,DOOR_Z]));assert(insideBuilding([0,0]));assert(!insideBuilding([4.4,3.8]));});
